<?php

declare(strict_types=1);
namespace Ispluka\Controllers;
use Ispluka\Core\Auth\AuthManager;use Ispluka\Core\Http\Request;use Ispluka\Core\Http\Response;use Ispluka\Core\Security\Csrf;use Ispluka\Services\RouterService;use InvalidArgumentException;use Throwable;
final class MikrotikRouterController
{
 public function __construct(private readonly RouterService $routers,private readonly AuthManager $auth,private readonly Csrf $csrf){}
 public function page():Response{$token=htmlspecialchars($this->csrf->token(),ENT_QUOTES,'UTF-8');return Response::text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080b12"><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/dashboard.css"><link rel="stylesheet" href="/assets/css/routeros.css"><title>RouterOS · MikroTik Routers</title></head><body class="dashboard-page routeros-page"><main class="main"><div class="container routeros-container"><div class="routeros-top"><div><div class="eyebrow routeros-eyebrow">NETWORK / ROUTEROS</div><h1>MikroTik Routers</h1><p class="muted">Monitor RouterOS health, manage connections and inspect live PPPoE sessions.</p></div><div class="routeros-toolbar"><button type="button" class="btn btn-secondary" id="refresh">↻ Refresh</button><button type="button" class="btn" id="add-router">＋ Add Router</button><a class="btn btn-secondary" href="/networking/mikrotik/enforcement-audit">PPPoE Audit</a><a class="btn btn-secondary" href="/">Dashboard</a></div></div><section class="routeros-summary"><div class="routeros-summary-card"><span>Routers</span><strong id="router-count">—</strong><small>Configured</small></div><div class="routeros-summary-card online"><span>Online</span><strong id="router-online">—</strong><small>Healthy connections</small></div><div class="routeros-summary-card offline"><span>Offline</span><strong id="router-offline">—</strong><small>Need attention</small></div></section><section id="router-form-panel" class="card stack router-form-card" hidden><div class="section-heading"><div><span class="section-kicker">ROUTEROS</span><h2 id="form-title">Add Router</h2><p class="muted">Configure a RouterOS endpoint using a supported transport.</p></div><button type="button" class="btn btn-secondary" id="close-router-form">Close</button></div><form id="router-form" class="form-grid"><input type="hidden" name="_csrf" value="'.$token.'"><input type="hidden" name="id" value=""><div><label>Name</label><input name="name" required maxlength="120" placeholder="AICN Core Router"></div><div><label>Code</label><input name="code" required maxlength="80" placeholder="CCR-01"></div><div class="field-wide"><label>Host / IP Address</label><input name="host" required maxlength="255" placeholder="103.186.218.150"></div><div><label>Connection Method</label><select name="connection_method" id="connection-method"><option value="api">RouterOS API</option><option value="ssh">SSH</option></select></div><div data-api-field><label>API Port</label><select name="api_port"><option value="8728">TCP 8728</option><option value="56983">TCP 56983</option></select></div><div data-ssh-field hidden><label>SSH Port</label><select name="ssh_port"><option value="8787">TCP 8787</option><option value="2288">TCP 2288</option><option value="22">TCP 22</option></select></div><div><label>Username</label><input name="username" required maxlength="120" autocomplete="off" placeholder="RouterOS username"></div><div><label>Password</label><input name="password" type="password" autocomplete="new-password" placeholder="Required for new router; optional on edit"></div><div data-api-field class="field-wide port-note"><span>RouterOS API</span><small>Allowed only: TCP 8728 or TCP 56983. Port cannot be entered manually.</small></div><div data-ssh-field hidden class="field-wide port-note"><span>RouterOS SSH</span><small>Allowed only: TCP 8787, TCP 2288 or TCP 22. Port cannot be entered manually.</small></div><div data-api-field class="field-wide"><label class="checkbox"><input name="verify_ssl" type="checkbox" checked> Verify SSL certificate</label></div><div class="actions field-wide"><button type="submit" id="save-router">Add Router</button><button type="button" class="btn-secondary" id="cancel-edit" hidden>Cancel Edit</button></div><p class="muted field-wide" id="form-message"></p></form></section><section class="card router-list-card"><div class="section-heading"><div><span class="section-kicker">INVENTORY</span><h2>RouterOS Inventory</h2><p class="muted" id="live-status">Loading router inventory…</p></div><div class="routeros-toolbar"><a class="btn btn-secondary" href="/networking/mikrotik/enforcement-audit">View Enforcement Audit</a><span class="live-badge"><i></i> Live</span></div></div><div class="router-table-wrap"><table class="router-table"><thead><tr><th>Router</th><th>Endpoint</th><th>Connection</th><th>Health</th><th>Last Seen</th><th>Actions</th></tr></thead><tbody id="routers"><tr><td colspan="6">Loading…</td></tr></tbody></table></div></section><section class="card stack pppoe-card"><div class="section-heading"><div><span class="section-kicker">LIVE NETWORK</span><h2>Active PPPoE Customers</h2><p class="muted" id="pppoe-live-label">Live RouterOS snapshot · select a router to load current sessions.</p></div></div><div class="routeros-summary pppoe-summary"><div class="routeros-summary-card"><span>Total Customers</span><strong id="pppoe-total">—</strong><small>Live PPPoE secrets</small></div><div class="routeros-summary-card online"><span>Active Customers</span><strong id="pppoe-active">—</strong><small>Live PPPoE sessions</small></div><div class="routeros-summary-card"><span>Showing</span><strong id="pppoe-showing">—</strong><small>After filters</small></div></div><div class="pppoe-toolbar"><div><label>Router</label><select id="pppoe-router"><option value="">Select router</option></select></div><div><label>Username filter</label><input id="pppoe-username" placeholder="Optional PPPoE username"></div><div><label>Uptime filter</label><select id="pppoe-uptime"><option value="all">All active</option><option value="lt1h">Less than 1 hour</option><option value="1to6h">1–6 hours</option><option value="6to24h">6–24 hours</option><option value="1to3d">1–3 days</option><option value="3dplus">3+ days</option></select></div><div class="actions"><button type="button" id="pppoe-load">Load Sessions</button></div></div><div class="router-table-wrap"><table class="router-table"><colgroup><col style="width:54px"><col style="width:190px"><col style="width:100px"><col style="width:150px"><col style="width:180px"><col style="width:130px"><col style="width:140px"></colgroup><thead><tr><th>#</th><th>Username</th><th>Service</th><th>Address</th><th>Caller ID</th><th id="pppoe-uptime-sort" role="button" tabindex="0" title="Toggle uptime sort">Uptime ↕</th><th>Action</th></tr></thead><tbody id="pppoe-sessions"><tr><td colspan="7">Select a router to load the live RouterOS snapshot.</td></tr></tbody></table></div></section></div></main><script src="/assets/js/mikrotik-routers.js?v=20260821-06" defer></script><script src="/assets/js/mikrotik-pppoe-fix.js?v=20260821-02" defer></script></body></html>');}
 public function index(Request $request):Response{try{return Response::json(['data'=>$this->routers->list($this->tenantId())]);}catch(Throwable $e){return $this->error($e);}}
 public function store(Request $request):Response{try{$id=$this->routers->create($this->tenantId(),$this->input($request,true));return Response::json(['data'=>['id'=>$id]],201);}catch(Throwable $e){return $this->error($e,422);}}
 public function update(Request $request):Response{try{$id=(int)$request->input('id',0);if($id<=0)throw new InvalidArgumentException('Router ID is required.');$this->routers->update($this->tenantId(),$id,$this->input($request,false));return Response::json(['data'=>['id'=>$id,'updated'=>true]]);}catch(Throwable $e){return $this->error($e,422);}}
 public function test(Request $request):Response{try{$id=(int)$request->input('id',$request->query('id',0));$result=$this->routers->testConnection($this->tenantId(),$id);return Response::json(['data'=>$result],$result['ok']?200:502);}catch(Throwable $e){return $this->error($e,422);}}
 public function status(Request $request):Response{try{$id=(int)$request->query('id',$request->input('id',0));$result=$this->routers->status($this->tenantId(),$id);return Response::json(['data'=>$result],$result['ok']?200:502);}catch(Throwable $e){return $this->error($e,422);}}
 public function activePppoe(Request $request):Response{try{$router=(int)$request->input('router_id',$request->query('router_id',0));$username=trim((string)$request->input('username',$request->query('username','')));if($router<1)throw new InvalidArgumentException('Router ID is required.');$result=$this->routers->activePppoe($this->tenantId(),$router,$username);return Response::json(['data'=>$result['sessions'],'meta'=>['total_customers'=>$result['total_customers'],'active_customers'=>$result['active_customers']]]);}catch(Throwable $e){return $this->error($e,422);}}
 public function disconnectPppoe(Request $request):Response{try{$router=(int)$request->input('router_id',0);$username=trim((string)$request->input('username',''));if($router<1||$username==='')throw new InvalidArgumentException('Router ID and PPPoE username are required.');return Response::json(['data'=>$this->routers->disconnectPppoe($this->tenantId(),$router,$username)]);}catch(Throwable $e){return $this->error($e,422);}}
 public function delete(Request $request):Response{try{$this->routers->delete($this->tenantId(),(int)$request->input('id',0));return Response::json(['data'=>['deleted'=>true]]);}catch(Throwable $e){return $this->error($e,422);}}
 private function input(Request $request,bool $creating):array{$method=strtolower((string)$request->input('connection_method','api'));return ['name'=>$request->input('name'),'code'=>$request->input('code'),'host'=>$request->input('host'),'connection_method'=>$method,'api_port'=>$request->input('api_port',8728),'ssh_port'=>$request->input('ssh_port',22),'username'=>$request->input('username'),'password'=>$request->input('password'),'verify_ssl'=>filter_var($request->input('verify_ssl',false),FILTER_VALIDATE_BOOLEAN)];}
 private function tenantId():int{$id=$this->auth->tenantId();if($id!==null)return $id;if($this->auth->roleCode()==='master_admin')return 0;throw new InvalidArgumentException('Tenant context is required.');}
 private function error(Throwable $e,int $status=400):Response{return Response::json(['error'=>['message'=>$e instanceof InvalidArgumentException||$e instanceof \RuntimeException?$e->getMessage():'Unable to process router request.']],$status);}
}
